mod api;
mod clipboard;
mod state;

use state::{AppState, Event};
use std::sync::{Arc, Mutex};
use tauri::Manager;

/// Called from JS for every input event captured in the webview.
#[tauri::command]
fn log_event(
    state: tauri::State<Arc<Mutex<AppState>>>,
    event_type: String,
    details: serde_json::Value,
) {
    let mut s = state.lock().unwrap();
    s.push(Event::new(event_type, details));
}

/// Called once on startup to record the screen / window dimensions.
#[tauri::command]
fn set_screen_size(
    state: tauri::State<Arc<Mutex<AppState>>>,
    width: u32,
    height: u32,
    title: String,
) {
    let mut s = state.lock().unwrap();
    s.screen_width = width;
    s.screen_height = height;
    s.window_title = title;
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    let shared = Arc::new(Mutex::new(AppState::default()));

    // Clipboard monitor thread
    clipboard::start_monitor(shared.clone());

    // HTTP API on a dedicated tokio runtime so it never blocks Tauri
    let api_state = shared.clone();
    std::thread::spawn(move || {
        tokio::runtime::Runtime::new()
            .unwrap()
            .block_on(api::serve(api_state));
    });

    // CUA_LOAD_URL: navigate the webview to an arbitrary URL instead of the
    // bundled index.html.  When unset, behaves as before (event-logger UI).
    // Useful for proxy/MITM tests: set CUA_LOAD_URL=https://example.com.
    let url_env = std::env::var("CUA_LOAD_URL").ok();

    tauri::Builder::default()
        .manage(shared)
        .invoke_handler(tauri::generate_handler![log_event, set_screen_size])
        .setup(move |app| {
            if let Some(url_str) = url_env {
                let win = app
                    .get_webview_window("main")
                    .expect("main window must exist");
                let url: tauri::Url = url_str.parse().expect("CUA_LOAD_URL is not a valid URL");
                win.navigate(url).ok();
            }
            Ok(())
        })
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

// Prevents additional console window on Windows in release
// Note: we intentionally allow the console on Windows so APP_HTTP_PORT=6769
// is printed to stdout where tests can see it.
fn main() {
    desktop_test_app_lib::run()
}

use arboard::Clipboard;
use std::{
    sync::{Arc, Mutex},
    thread,
    time::Duration,
};

use crate::state::{AppState, Event};

pub fn start_monitor(state: Arc<Mutex<AppState>>) {
    thread::spawn(move || {
        let Ok(mut cb) = Clipboard::new() else {
            eprintln!("[clipboard] failed to open clipboard — monitor disabled");
            return;
        };

        let mut last = String::new();

        loop {
            thread::sleep(Duration::from_millis(500));

            let current = cb.get_text().unwrap_or_default();
            if current != last {
                last = current.clone();
                let mut s = state.lock().unwrap();
                s.clipboard = current.clone();
                s.push(Event::new(
                    "clipboard_change",
                    serde_json::json!({ "text": current }),
                ));
            }
        }
    });
}

use serde::{Deserialize, Serialize};
use std::collections::VecDeque;
use std::time::{SystemTime, UNIX_EPOCH};

const MAX_EVENTS: usize = 2000;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Event {
    pub timestamp_ms: u64,
    #[serde(rename = "type")]
    pub event_type: String,
    pub details: serde_json::Value,
}

impl Event {
    pub fn new(event_type: impl Into<String>, details: serde_json::Value) -> Self {
        let timestamp_ms = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis() as u64;
        Self {
            timestamp_ms,
            event_type: event_type.into(),
            details,
        }
    }
}

#[derive(Debug, Default)]
pub struct AppState {
    pub events: VecDeque<Event>,
    pub clipboard: String,
    pub screen_width: u32,
    pub screen_height: u32,
    pub window_title: String,
}

impl AppState {
    pub fn push(&mut self, event: Event) {
        self.events.push_back(event);
        if self.events.len() > MAX_EVENTS {
            self.events.pop_front();
        }
    }

    pub fn reset(&mut self) -> usize {
        let n = self.events.len();
        self.events.clear();
        n
    }

    pub fn all_events(&self) -> Vec<Event> {
        self.events.iter().cloned().collect()
    }
}
